INSERT INTO text_fill (slug, descr, how, tips, mist) VALUES
  ($t$wyciskanie-sztangi-lezac$t$, $t$Leżysz na ławce i wypychasz sztangę znad klatki prosto w górę.$t$, $t$Połóż się na ławce, stopy płasko na podłodze. Chwyć sztangę nieco szerzej niż barki i zdejmij ją z podpórek. Opuść ją powoli do klatki i wypchnij w górę.$t$, $t$Łopatki ściągnięte i oparte o ławkę. Stopy stabilnie na podłodze. Opuszczaj sztangę wolno.$t$, $t$Nie odbijaj sztangi od klatki.$t$),
  ($t$wyciskanie-hantli-nad-g-owe$t$, $t$Siedzisz lub stoisz z hantlami przy barkach i wypychasz je nad głowę.$t$, $t$Unieś hantle na wysokość barków, dłonie skierowane do przodu. Wypchnij je nad głowę, aż ręce będą prawie proste, potem wolno opuść do barków.$t$, $t$Brzuch napięty. Nie wyginaj pleców do tyłu. Zacznij od lekkich hantli.$t$, $t$Nie odchylaj tułowia do tyłu.$t$),
  ($t$plank$t$, $t$Podpierasz się na przedramionach i palcach stóp, ciało tworzy prostą linię.$t$, $t$Połóż przedramiona na podłodze, łokcie pod barkami. Unieś ciało na palcach stóp i napnij brzuch oraz pośladki. Utrzymaj pozycję 20–30 sekund.$t$, $t$Ciało w jednej linii od głowy do pięt. Oddychaj spokojnie. Zacznij od krótkiego czasu.$t$, $t$Nie opuszczaj bioder.$t$),
  ($t$przysiad-goblet-z-hantlem$t$, $t$Trzymasz hantel przy klatce i robisz przysiad.$t$, $t$Stań na szerokość barków, hantel trzymaj oburącz przy klatce. Zegnij kolana i biodra i zejdź w dół, plecy proste. Wypchnij się piętami do stania.$t$, $t$Plecy proste, klatka do przodu. Kolana w linii stóp. Pięty zostają na podłodze.$t$, $t$Nie pozwalaj kolanom uciekać do środka.$t$),
  ($t$przysiad-do-skrzyni$t$, $t$Siadasz tyłem na ławkę lub skrzynię i wstajesz z obciążeniem.$t$, $t$Ustaw ławkę za sobą na takiej wysokości, by uda były mniej więcej poziomo. Zejdź powoli biodrami do tyłu, aż lekko usiądziesz. Bez odbijania się wstań, wypychając się piętami.$t$, $t$Siadaj kontrolowanie, nie opadaj. Brzuch napięty. Kolana w linii stóp.$t$, $t$Nie siadaj całym ciężarem i nie odbijaj się od ławki.$t$),
  ($t$przysiad-do-skrzyni-z-masa-w-asnego-cia-a$t$, $t$Siadasz na krzesło lub niską skrzynię i wstajesz bez dodatkowego ciężaru.$t$, $t$Stań przed krzesłem, ręce wyciągnij przed siebie. Powoli usiądź, odsuwając biodra do tyłu. Dotknij siedziska i wstań, odpychając się piętami.$t$, $t$Schodź wolno. Kolana w linii stóp. Oddychaj równo.$t$, $t$Nie opadaj na krzesło bez kontroli.$t$),
  ($t$wypychanie-nog-na-suwnicy-45$t$, $t$Siedzisz w maszynie i wypychasz platformę nogami.$t$, $t$Usiądź w maszynie, plecy oparte, stopy na platformie na szerokość barków. Odblokuj zabezpieczenia i zegnij kolana. Wypchnij platformę prawie do wyprostu nóg, nie blokując kolan.$t$, $t$Plecy i pośladki przylegają do oparcia. Kolana w linii stóp. Nie prostuj kolan do końca.$t$, $t$Nie odrywaj pośladków od siedziska.$t$),
  ($t$przysiad-wykroczny-z-podparciem$t$, $t$Robisz wykrok jedną nogą do przodu, przytrzymując się ściany lub drążka.$t$, $t$Stań bokiem przy ścianie i przytrzymaj się ręką. Zrób krok do przodu i opuść biodra prosto w dół. Wypchnij się przednią nogą i wróć.$t$, $t$Tułów prosto. Przednie kolano nad stopą. Z czasem podpieraj się coraz mniej.$t$, $t$Nie pochylaj tułowia do przodu.$t$),
  ($t$wykrok-w-ty$t$, $t$Cofasz jedną nogę w tył i opuszczasz biodra, potem wracasz do stania.$t$, $t$Stań prosto. Zrób duży krok do tyłu i opuść tylne kolano blisko podłogi. Odepchnij się przednią nogą i wróć do stania.$t$, $t$Tułów prosto. Przednie kolano nad stopą. Krok na tyle duży, by tylne kolano opadło nisko.$t$, $t$Nie rób zbyt małego kroku.$t$),
  ($t$wykroki-chodzone$t$, $t$Idziesz do przodu, w każdym kroku opuszczając tylne kolano blisko podłogi.$t$, $t$Stań prosto, ręce wzdłuż ciała. Zrób duży krok i opuść tylne kolano. Wstań, przenosząc ciężar na przednią nogę, i zrób kolejny krok drugą nogą.$t$, $t$Tułów prosto, wzrok przed siebie. Kroki duże i spokojne. Przednie kolano nad stopą.$t$, $t$Nie rób zbyt małych kroków.$t$),
  ($t$wejscie-na-podest$t$, $t$Wchodzisz na stabilny podest jedną nogą, potem schodzisz.$t$, $t$Stań przed podestem i postaw na nim całą stopę. Wypchnij się tą nogą i wejdź na górę. Zejdź powoli i powtórz, potem zmień nogę.$t$, $t$Pracuje noga na podeście, nie odpychaj się tylną. Stopa płasko. Zacznij od niskiego podestu.$t$, $t$Nie odpychaj się od podłogi tylną nogą.$t$),
  ($t$prostowanie-nog-na-maszynie$t$, $t$Siedzisz w maszynie i prostujesz nogi, unosząc wałek.$t$, $t$Usiądź i ustaw wałek tuż nad stopami. Wyprostuj nogi, napnij uda na górze. Powoli opuść ciężar.$t$, $t$Plecy oparte, ruch wolny. Nie szarp. Dobierz lekki ciężar.$t$, $t$Nie szarp i nie odrywaj się od siedzenia.$t$),
  ($t$martwy-ciag-rumunski-ze-sztanga$t$, $t$Z lekko ugiętymi kolanami przesuwasz biodra do tyłu i opuszczasz sztangę wzdłuż nóg.$t$, $t$Stań na szerokość bioder, sztanga w rękach przed udami. Odsuń biodra do tyłu i prowadź sztangę blisko nóg, aż poczujesz rozciąganie z tyłu ud. Wróć do stania, popychając biodra do przodu.$t$, $t$Plecy proste przez cały ruch. Sztanga blisko nóg. Ruch zaczyna się w biodrach.$t$, $t$Nie zaokrąglaj pleców.$t$),
  ($t$martwy-ciag-rumunski-z-hantlami$t$, $t$Z lekko ugiętymi kolanami przesuwasz biodra do tyłu i opuszczasz hantle wzdłuż nóg.$t$, $t$Stań na szerokość bioder, hantle przed udami. Odsuń biodra do tyłu i prowadź hantle blisko nóg, aż poczujesz rozciąganie z tyłu ud. Wróć do stania, popychając biodra do przodu.$t$, $t$Plecy proste przez cały ruch. Hantle blisko nóg. Ruch zaczyna się w biodrach.$t$, $t$Nie zaokrąglaj pleców.$t$),
  ($t$martwy-ciag-z-trap-barem$t$, $t$Stoisz w środku sześciokątnej sztangi i podnosisz ją z podłogi, prostując nogi i biodra.$t$, $t$Wejdź do środka sztangi, stopy na szerokość bioder. Chwyć uchwyty, wyprostuj plecy i napnij brzuch. Wstań, odpychając się nogami, i opuść sztangę z kontrolą.$t$, $t$Plecy proste. Biodra i barki unoszą się razem. Sztanga blisko ciała.$t$, $t$Nie zaokrąglaj pleców.$t$),
  ($t$martwy-ciag-z-kettlebell$t$, $t$Podnosisz odważnik z podłogi, prostując nogi i biodra.$t$, $t$Stań nad odważnikiem, stopy nieco szerzej niż biodra. Odsuń biodra do tyłu, chwyć odważnik oburącz i napnij brzuch. Wstań, wypychając podłogę piętami, i opuść odważnik z kontrolą.$t$, $t$Plecy proste. Odważnik blisko nóg. Na górze ściśnij pośladki.$t$, $t$Nie zaokrąglaj pleców.$t$),
  ($t$hip-thrust$t$, $t$Plecami opartymi o ławkę unosisz biodra z ciężarem na biodrach.$t$, $t$Oprzyj łopatki o ławkę, ciężar połóż na biodrach. Stopy na podłodze, kolana zgięte. Unieś biodra do prostej linii z tułowiem i mocno ściśnij pośladki, potem opuść.$t$, $t$Broda lekko do klatki. Kolana nad stopami. Na górze ściśnij pośladki.$t$, $t$Nie wyginaj dolnych pleców na górze.$t$),
  ($t$glute-bridge$t$, $t$Leżysz na plecach i unosisz biodra, zginając kolana.$t$, $t$Połóż się na plecach, kolana zgięte, stopy blisko pośladków. Unieś biodra, aż ciało będzie w linii od kolan do barków. Ściśnij pośladki i wolno opuść.$t$, $t$Stopy płasko na podłodze. Ściśnij pośladki na górze. Oddychaj równo.$t$, $t$Nie wyginaj dolnych pleców zamiast unosić biodra.$t$),
  ($t$wspiecia-na-palce-stojac$t$, $t$Stoisz na krawędzi stopnia i unosisz pięty, wspinając się na palce.$t$, $t$Stań na krawędzi stopnia, pięty poza krawędzią. Opuść pięty nisko, potem unieś się jak najwyżej na palcach. Powoli opuść.$t$, $t$Ruch pełny i wolny. Kolana proste. Przytrzymaj się czegoś dla równowagi.$t$, $t$Nie rób ruchu szybko i połowicznie.$t$),
  ($t$wyciskanie-hantli-na-awce-skosnej-dodatniej$t$, $t$Leżysz na ławce nachylonej do góry i wypychasz hantle nad klatkę.$t$, $t$Ustaw ławkę lekko do góry (ok. 30–45°). Połóż się, hantle trzymaj przy klatce. Wypchnij je w górę i lekko do siebie, potem opuść wolno.$t$, $t$Łopatki ściągnięte. Łokcie nie za szeroko. Nie ustawiaj ławki zbyt stromo.$t$, $t$Nie ustawiaj ławki zbyt stromo.$t$),
  ($t$wyciskanie-na-maszynie-siedzac$t$, $t$Siedzisz w maszynie i wypychasz uchwyty przed siebie.$t$, $t$Ustaw siedzisko tak, by uchwyty były na wysokości środka klatki. Plecy oparte, chwyć uchwyty. Wypchnij je do przodu, nie prostując łokci do końca, i wolno wróć.$t$, $t$Plecy oparte. Barki nisko. Ruch spokojny.$t$, $t$Nie unoś barków do uszu.$t$),
  ($t$pompki-na-podwyzszeniu$t$, $t$Robisz pompkę z dłońmi opartymi o stabilne podwyższenie.$t$, $t$Oprzyj dłonie o ławkę lub stół, nieco szerzej niż barki. Ciało w jednej linii. Zegnij łokcie i zbliż klatkę do podwyższenia, potem wypchnij się w górę.$t$, $t$Brzuch napięty. Ciało w linii. Im wyżej dłonie, tym łatwiej.$t$, $t$Nie opuszczaj bioder.$t$),
  ($t$pompki-klasyczne$t$, $t$Podpierasz się na dłoniach i palcach stóp i uginasz ręce, opuszczając klatkę.$t$, $t$Dłonie nieco szerzej niż barki, ciało w jednej linii od głowy do pięt. Zegnij łokcie i opuść klatkę nisko nad podłogę. Wypchnij się w górę.$t$, $t$Brzuch i pośladki napięte. Łokcie lekko do tyłu. Patrz w podłogę.$t$, $t$Nie opuszczaj bioder.$t$),
  ($t$pompki-na-kolanach$t$, $t$Robisz pompkę, opierając się na dłoniach i kolanach.$t$, $t$Uklęknij, dłonie nieco szerzej niż barki. Ciało w linii od kolan do głowy. Zegnij łokcie i opuść klatkę, potem wypchnij się w górę.$t$, $t$Plecy proste. Brzuch napięty. Gdy jest łatwo, przejdź do pompek na podwyższeniu.$t$, $t$Nie zapadaj się w biodrach.$t$),
  ($t$sciaganie-drazka-wyciagu-gornego-chwytem-neutralnym$t$, $t$Siedzisz przy wyciągu i ściągasz uchwyt z góry do klatki, dłonie zwrócone do siebie.$t$, $t$Usiądź, uda zablokuj pod wałkami, chwyć uchwyt. Ściągnij go do górnej części klatki, łokcie w dół. Wolno wróć do góry.$t$, $t$Klatka lekko do przodu. Łokcie w dół, nie do tyłu. Ciągnij plecami, nie samymi rękami.$t$, $t$Nie odchylaj się mocno do tyłu.$t$),
  ($t$sciaganie-drazka-wyciagu-gornego-szerokim-nachwytem$t$, $t$Siedzisz przy wyciągu i ściągasz drążek z góry do klatki szerokim chwytem.$t$, $t$Chwyć drążek szerzej niż barki, dłonie od siebie. Usiądź, klatka lekko do przodu. Ściągnij drążek do górnej części klatki, łokcie w dół, i wolno wróć.$t$, $t$Ściągaj do klatki. Łopatki w dół. Bez bujania.$t$, $t$Nie ściągaj drążka za głowę.$t$),
  ($t$sciaganie-drazka-wyciagu-gornego-podchwytem$t$, $t$Siedzisz przy wyciągu i ściągasz drążek z góry do klatki, dłonie zwrócone do siebie.$t$, $t$Chwyć drążek od spodu na szerokość barków. Ściągnij go do górnej części klatki, łokcie przy ciele, i wolno wróć.$t$, $t$Łokcie w dół. Klatka do przodu. Ciągnij plecami.$t$, $t$Nie odchylaj się do tyłu.$t$),
  ($t$podciaganie-na-maszynie-wspomagajacej$t$, $t$Podciągasz się na drążku z pomocą maszyny, która odciąża część ciężaru.$t$, $t$Stań lub uklęknij na platformie. Chwyć drążek na szerokość barków. Podciągnij się, łokcie w dół, aż broda będzie nad drążkiem, i wolno opuść.$t$, $t$Łopatki w dół. Ruch wolny. Z czasem zmniejszaj pomoc.$t$, $t$Nie unoś barków do uszu.$t$),
  ($t$wios-owanie-hantlami-z-podparciem-klatki$t$, $t$Leżysz klatką na nachylonej ławce i przyciągasz hantle do boków.$t$, $t$Połóż się klatką na ławce nachylonej, hantle w opuszczonych rękach. Przyciągnij hantle do boków, łokcie blisko ciała. Na górze ściągnij łopatki i wolno opuść.$t$, $t$Głowa w przedłużeniu pleców. Ściągaj łopatki. Ruch bez szarpania.$t$, $t$Nie szarp i nie unoś barków.$t$),
  ($t$wios-owanie-na-maszynie$t$, $t$Siedzisz w maszynie i przyciągasz uchwyty do tułowia.$t$, $t$Usiądź, klatka oparta o podpórkę. Chwyć uchwyty, przyciągnij je do boków, łokcie blisko ciała. Wolno wróć.$t$, $t$Plecy proste. Ściągnij łopatki na końcu. Nie bujaj tułowiem.$t$, $t$Nie bujaj tułowiem.$t$),
  ($t$wios-owanie-jednoracz-hantlem$t$, $t$Jedną ręką i kolanem opierasz się o ławkę, drugą przyciągasz hantel do boku.$t$, $t$Oprzyj kolano i dłoń na ławce, plecy proste. Hantel w drugiej ręce wisi pod barkiem. Przyciągnij go do biodra i wolno opuść. Zrób serię i zmień stronę.$t$, $t$Plecy poziomo i proste. Łokieć blisko ciała. Bez skręcania tułowia.$t$, $t$Nie skręcaj tułowia.$t$),
  ($t$wios-owanie-guma-oporowa$t$, $t$Przyciągasz gumę do brzucha, ściągając łopatki.$t$, $t$Zaczep gumę o stabilny punkt na wysokości brzucha. Stań lub usiądź, chwyć końce gumy. Przyciągnij ją do pępka, łokcie blisko ciała, i wolno wróć.$t$, $t$Plecy proste. Ściągnij łopatki. Guma cały czas napięta.$t$, $t$Nie odchylaj się do tyłu.$t$),
  ($t$wyciskanie-na-maszynie-nad-g-owe$t$, $t$Siedzisz w maszynie i wypychasz uchwyty nad głowę.$t$, $t$Ustaw siedzisko tak, by uchwyty były na wysokości barków. Plecy oparte. Wypchnij uchwyty w górę, nie prostując łokci do końca, i wolno wróć.$t$, $t$Plecy oparte. Barki nisko. Ruch spokojny.$t$, $t$Nie odginaj pleców do tyłu.$t$),
  ($t$wyciskanie-hantli-siedzac$t$, $t$Siedzisz i wypychasz hantle z wysokości barków nad głowę.$t$, $t$Usiądź z oparciem, hantle przy barkach. Wypchnij je w górę, aż ręce będą prawie proste, i wolno opuść do barków.$t$, $t$Brzuch napięty. Plecy oparte. Hantle nie uderzają o siebie.$t$, $t$Nie odchylaj się do tyłu.$t$),
  ($t$unoszenie-hantli-bokiem$t$, $t$Stoisz z hantlami przy bokach i unosisz ręce w bok do wysokości barków.$t$, $t$Stań prosto, hantle wzdłuż ciała, łokcie lekko zgięte. Unieś ręce bokiem do wysokości barków, nie wyżej. Wolno opuść.$t$, $t$Użyj lekkich hantli. Łokcie lekko zgięte. Bez bujania.$t$, $t$Nie unoś hantli powyżej barków.$t$),
  ($t$odwrotne-rozpietki-na-maszynie-pec-deck$t$, $t$Siedzisz przodem do oparcia maszyny i odwodzisz ręce do tyłu.$t$, $t$Usiądź przodem do oparcia, klatka przy nim. Chwyć uchwyty. Rozsuń ręce na boki i do tyłu, ściągając łopatki. Wolno wróć.$t$, $t$Klatka oparta. Łokcie lekko zgięte. Ściągnij łopatki.$t$, $t$Nie unoś barków.$t$),
  ($t$odwrotne-rozpietki-z-hantlami$t$, $t$Pochylasz się z hantlami w rękach i unosisz ręce na boki.$t$, $t$Pochyl tułów, plecy proste, hantle zwisają pod barkami. Unieś ręce na boki do wysokości tułowia, ściągając łopatki. Wolno opuść.$t$, $t$Plecy proste. Lekkie hantle. Łokcie lekko zgięte.$t$, $t$Nie bujaj tułowiem.$t$),
  ($t$uginanie-ramion-ze-sztanga$t$, $t$Stoisz ze sztangą w rękach i uginasz ramiona.$t$, $t$Stań prosto, sztanga w opuszczonych rękach, chwyt od spodu. Zegnij łokcie i unieś sztangę do barków. Wolno opuść.$t$, $t$Łokcie przy bokach. Plecy proste. Opuszczaj wolno.$t$, $t$Nie bujaj tułowiem.$t$),
  ($t$uginanie-ramion-ze-sztanga-ez$t$, $t$Stoisz ze sztangą z wygiętym gryfem i uginasz ramiona.$t$, $t$Stań prosto, sztanga w opuszczonych rękach, chwyt od spodu. Zegnij łokcie i unieś sztangę do barków. Wolno opuść.$t$, $t$Łokcie przy bokach. Plecy proste. Opuszczaj wolno.$t$, $t$Nie bujaj tułowiem.$t$),
  ($t$uginanie-ramion-z-hantlami$t$, $t$Stoisz z hantlami w rękach i uginasz ramiona.$t$, $t$Stań prosto, hantle w opuszczonych rękach, dłonie do przodu. Zegnij łokcie i unieś hantle do barków. Wolno opuść.$t$, $t$Łokcie przy bokach. Plecy proste. Opuszczaj wolno.$t$, $t$Nie bujaj tułowiem.$t$),
  ($t$prostowanie-ramion-z-lina-na-wyciagu$t$, $t$Stoisz przy wyciągu i prostujesz ręce w dół, ciągnąc linę.$t$, $t$Stań przy wyciągu, chwyć linę, łokcie przy bokach. Wyprostuj ręce w dół, rozchylając końce liny. Wolno wróć.$t$, $t$Łokcie przy bokach. Tułów prosto. Ruch tylko w łokciach.$t$, $t$Nie ruszaj łokciami do przodu.$t$),
  ($t$dead-bug$t$, $t$Leżysz na plecach z rękami i nogami w górze i wolno opuszczasz na przemian rękę i przeciwną nogę.$t$, $t$Połóż się na plecach, ręce w górę, kolana zgięte nad biodrami. Opuść wolno prawą rękę i lewą nogę ku podłodze, nie odrywając dolnych pleców. Wróć i zrób drugą stronę.$t$, $t$Dolne plecy przy podłodze. Oddychaj równo. Rób wolno.$t$, $t$Nie odrywaj dolnych pleców od podłogi.$t$),
  ($t$bird-dog$t$, $t$Na czworakach wyciągasz jednocześnie jedną rękę i przeciwną nogę.$t$, $t$Stań na czworakach, dłonie pod barkami, kolana pod biodrami. Wyciągnij prawą rękę i lewą nogę do linii z tułowiem, zatrzymaj się i wróć. Zmień strony.$t$, $t$Plecy proste, biodra równo. Patrz w podłogę. Rób wolno.$t$, $t$Nie przechylaj bioder na bok.$t$),
  ($t$pallof-press$t$, $t$Stoisz bokiem do wyciągu i wypychasz ręce przed siebie, nie dając się skręcić.$t$, $t$Stań bokiem do wyciągu, uchwyt trzymaj przy klatce. Wypchnij ręce przed siebie i przytrzymaj. Wróć do klatki.$t$, $t$Biodra i barki prosto przed siebie. Brzuch napięty. Oddychaj.$t$, $t$Nie pozwól, by wyciąg skręcał tułów.$t$),
  ($t$spiecia-brzucha-na-wyciagu$t$, $t$Klęczysz przy wyciągu i zginasz tułów, ściągając linę w dół.$t$, $t$Uklęknij przed wyciągiem, linę trzymaj przy głowie. Zaokrąglij tułów w dół, łokcie do kolan. Wolno wróć.$t$, $t$Ruch z brzucha, nie z rąk. Biodra stoją w miejscu. Lekki ciężar.$t$, $t$Nie ciągnij rękami zamiast brzuchem.$t$),
  ($t$unoszenie-kolan-w-zwisie$t$, $t$Wisisz na drążku i unosisz kolana do klatki.$t$, $t$Chwyć drążek i zwiśnij. Unieś kolana do klatki, nie bujając ciałem. Wolno opuść.$t$, $t$Bez bujania. Brzuch napięty. Opuszczaj wolno.$t$, $t$Nie buj całym ciałem.$t$),
  ($t$wyciskanie-hantli-lezac$t$, $t$Leżysz na ławce i wypychasz hantle znad klatki prosto w górę.$t$, $t$Połóż się na ławce, hantle przy klatce. Wypchnij je w górę i lekko do siebie, potem wolno opuść do klatki.$t$, $t$Łopatki ściągnięte. Stopy na podłodze. Opuszczaj wolno.$t$, $t$Nie opuszczaj hantli zbyt nisko ani zbyt szybko.$t$),
  ($t$pompki-z-obciazeniem$t$, $t$Robisz pompkę z dodatkowym ciężarem na plecach.$t$, $t$Przyjmij pozycję do pompki, ciężar (plecak lub talerz) połóż na plecach. Zegnij łokcie i opuść klatkę nisko, potem wypchnij się w górę.$t$, $t$Ciało w jednej linii. Zacznij od małego ciężaru. Ciężar leży stabilnie.$t$, $t$Nie opuszczaj bioder.$t$),
  ($t$prostowanie-ramion-nad-g-owa-z-hantlem$t$, $t$Trzymasz hantel nad głową, zginasz łokcie za głową i prostujesz ręce.$t$, $t$Stań lub usiądź, hantel trzymaj oburącz nad głową. Zegnij łokcie, opuszczając hantel za głowę, potem wyprostuj ręce w górę.$t$, $t$Łokcie blisko głowy. Brzuch napięty. Lekki ciężar.$t$, $t$Nie rozstawiaj łokci szeroko.$t$),
  ($t$wspiecia-na-palce-jednostronne-stojac$t$, $t$Stoisz na jednej nodze i unosisz piętę, wspinając się na palec.$t$, $t$Stań na jednej nodze, drugą zegnij. Przytrzymaj się ściany. Unieś się na palcach jak najwyżej i wolno opuść.$t$, $t$Trzymaj się dla równowagi. Ruch wolny i pełny. Po serii zmień nogę.$t$, $t$Nie rób ruchu szybko.$t$),
  ($t$hollow-body-hold$t$, $t$Leżysz na plecach i unosisz ramiona i nogi tuż nad podłogą.$t$, $t$Połóż się na plecach, dolne plecy przyciśnij do podłogi. Unieś ramiona i proste nogi nad podłogę i utrzymaj pozycję 10–20 sekund.$t$, $t$Dolne plecy przy podłodze. Oddychaj spokojnie. Gdy za trudno, ugnij kolana.$t$, $t$Nie odrywaj dolnych pleców od podłogi.$t$),
  ($t$rotacje-rosyjskie$t$, $t$Siedzisz z lekko odchylonym tułowiem i skręcasz tułów z boku na bok.$t$, $t$Usiądź, kolana zgięte, tułów lekko odchylony. Złącz dłonie i skręcaj tułów raz w jedną, raz w drugą stronę.$t$, $t$Plecy proste. Skręcaj tułów, nie same ręce. Rób wolno.$t$, $t$Nie zaokrąglaj pleców.$t$),
  ($t$woodchop-na-wyciagu$t$, $t$Stoisz bokiem do wyciągu i ciągniesz linę przez tułów, jakbyś rąbał drewno.$t$, $t$Stań bokiem do wyciągu, chwyć uchwyt oburącz. Pociągnij go po skosie w dół przez przód tułowia, skręcając tułów. Wolno wróć.$t$, $t$Biodra i stopy stabilne. Ruch płynny. Lekki ciężar.$t$, $t$Nie ciągnij samymi rękami.$t$),
  ($t$unoszenie-nog-w-lezeniu$t$, $t$Leżysz na plecach i unosisz proste nogi, potem wolno je opuszczasz.$t$, $t$Połóż się na plecach, ręce przy bokach. Unieś proste nogi do pionu i wolno opuść, nie dotykając podłogi.$t$, $t$Dolne plecy przy podłodze. Kolana lekko zgięte, jeśli trzeba. Rób wolno.$t$, $t$Nie wyginaj dolnych pleców.$t$),
  ($t$rozciaganie-gumy-przed-klatka-band-pull-apart$t$, $t$Rozciągasz gumę przed sobą, rozkładając ręce na boki.$t$, $t$Stań prosto, gumę trzymaj oburącz przed sobą na szerokość barków, ręce proste. Rozciągnij ją, rozkładając ręce na boki i ściągając łopatki. Wolno wróć.$t$, $t$Ręce proste. Łopatki do siebie. Barki nisko.$t$, $t$Nie unoś barków.$t$),
  ($t$rotacja-zewnetrzna-barku-z-guma-oporowa$t$, $t$Łokieć masz przy boku i obracasz przedramię na zewnątrz, rozciągając gumę.$t$, $t$Zaczep gumę z boku, łokieć zgięty do kąta prostego, przy ciele. Obróć przedramię na zewnątrz i wolno wróć.$t$, $t$Łokieć przy ciele. Ruch wolny. Lekka guma.$t$, $t$Nie odsuwaj łokcia od ciała.$t$),
  ($t$francuskie-prostowanie-ramion-guma-oporowa-zza-g-owy$t$, $t$Trzymasz gumę za głową i prostujesz ręce w górę.$t$, $t$Zaczep gumę nisko za sobą i chwyć ją nad głową, łokcie zgięte. Wyprostuj ręce w górę i wolno wróć.$t$, $t$Łokcie blisko głowy. Brzuch napięty. Ruch tylko w łokciach.$t$, $t$Nie rozstawiaj łokci.$t$),
  ($t$skoki-pogo$t$, $t$Skaczesz w miejscu na samych palcach, prawie bez uginania kolan.$t$, $t$Stań prosto, ręce przy bokach. Odbijaj się od palców, kolana prawie proste, i lądując, od razu odbijaj się znowu.$t$, $t$Lądowanie miękkie. Pięty nie dotykają podłogi. Tułów prosto.$t$, $t$Nie ląduj na piętach.$t$),
  ($t$skok-z-zamachem$t$, $t$Zamachem rąk odbijasz się i skaczesz jak najwyżej.$t$, $t$Stań na szerokość barków. Zegnij lekko kolana, zamachnij ręce w tył, potem w górę i wyskocz. Lądując, zegnij kolana i stań miękko.$t$, $t$Lądowanie na obu nogach i miękko. Kolana nad stopami. Patrz przed siebie.$t$, $t$Nie ląduj sztywno na prostych nogach.$t$),
  ($t$nauka-ladowania$t$, $t$Ćwiczysz miękkie lądowanie po niewielkim podskoku.$t$, $t$Stań na szerokość barków. Zrób mały podskok i wyląduj jednocześnie na obu stopach, uginając kolana i biodra. Zatrzymaj się na 2 sekundy i wstań.$t$, $t$Lądowanie ciche i miękkie. Kolana w linii stóp. Zatrzymaj się w pozycji.$t$, $t$Nie pozwól kolanom uciekać do środka.$t$),
  ($t$przeskoki-boczne-z-nogi-na-noge$t$, $t$Odbijasz się z jednej nogi w bok i lądujesz na drugiej.$t$, $t$Stań na jednej nodze. Odbij się w bok i wyląduj na drugiej nodze, uginając kolano. Zatrzymaj się na chwilę i skocz z powrotem.$t$, $t$Lądowanie miękkie, kolano nad stopą. Zatrzymaj się po lądowaniu. Skacz tylko tak daleko, jak panujesz nad ruchem.$t$, $t$Nie pozwól kolanu uciekać do środka.$t$),
  ($t$wspiecia-na-palce-obunoj-stojac$t$, $t$Stoisz i unosisz pięty, wspinając się na palce.$t$, $t$Stań na szerokość bioder, najlepiej przy ścianie. Unieś pięty jak najwyżej i wolno opuść.$t$, $t$Ruch wolny i pełny. Kolana proste. Przytrzymaj się dla równowagi.$t$, $t$Nie rób ruchu szybko i połowicznie.$t$),
  ($t$wejscie-na-niskie-podwyzszenie-z-podparciem$t$, $t$Wchodzisz na niski stopień, przytrzymując się ściany lub poręczy.$t$, $t$Stań przed niskim stopniem i przytrzymaj się. Postaw stopę na stopniu i wejdź na górę, prostując nogę. Zejdź wolno i zmień nogę.$t$, $t$Cała stopa na stopniu. Pracuje noga na stopniu. Tułów prosto.$t$, $t$Nie odpychaj się mocno tylną nogą.$t$),
  ($t$podciaganie-podchwytem-chin-up$t$, $t$Wisisz na drążku, dłonie zwrócone do siebie, i podciągasz się brodą nad drążek.$t$, $t$Chwyć drążek od spodu na szerokość barków i zwiśnij. Podciągnij się, łokcie w dół, aż broda będzie nad drążkiem. Wolno opuść się do prostych rąk.$t$, $t$Łopatki w dół. Brzuch napięty. Opuszczaj się wolno.$t$, $t$Nie bujaj się i nie skracaj ruchu na dole.$t$),
  ($t$wioslowanie-w-zwisie-pod-sztanga-australijskie-podciaganie$t$, $t$Leżysz pod niskim drążkiem i podciągasz klatkę do drążka, ciało proste.$t$, $t$Połóż się pod niskim, stabilnym drążkiem, chwyć go nachwytem. Ciało proste, pięty na podłodze. Podciągnij klatkę do drążka i wolno opuść.$t$, $t$Ciało w jednej linii. Łopatki do siebie. Łatwiej: ugnij kolana.$t$, $t$Nie opuszczaj bioder.$t$),
  ($t$przysiad-z-masa-wlasnego-ciala$t$, $t$Robisz przysiad bez dodatkowego ciężaru.$t$, $t$Stań na szerokość barków, ręce przed sobą. Zegnij kolana i biodra i zejdź w dół, plecy proste. Wypchnij się piętami do stania.$t$, $t$Plecy proste. Kolana w linii stóp. Pięty na podłodze.$t$, $t$Nie odrywaj pięt.$t$),
  ($t$lokiec-do-kolana-sklon-skosny-stojac$t$, $t$Stoisz i przyciągasz łokieć do przeciwnego kolana, skręcając tułów.$t$, $t$Stań na szerokość barków, dłonie przy głowie. Unieś kolano i skręć tułów, dotykając łokciem kolana po przeciwnej stronie. Wróć i zmień stronę.$t$, $t$Ruch z brzucha. Rób wolno. Patrz przed siebie.$t$, $t$Nie ciągnij głowy rękami.$t$),
  ($t$dipy-na-lawce$t$, $t$Opierasz dłonie o ławkę za plecami i uginasz łokcie, opuszczając biodra.$t$, $t$Usiądź na brzegu ławki, dłonie obok bioder. Przesuń biodra przed ławkę i zegnij łokcie, opuszczając ciało. Wypchnij się w górę.$t$, $t$Łokcie do tyłu, nie na boki. Barki nisko. Schodź tylko tak nisko, jak komfortowo.$t$, $t$Nie schodź zbyt nisko ani nie unoś barków.$t$),
  ($t$nozyce-poziome-flutter-kicks$t$, $t$Leżysz na plecach i machasz na przemian prostymi nogami tuż nad podłogą.$t$, $t$Połóż się na plecach, ręce pod biodrami. Unieś proste nogi nisko nad podłogę i machaj nimi na przemian w górę i w dół.$t$, $t$Dolne plecy przy podłodze. Oddychaj równo. Gdy za trudno, unieś nogi wyżej.$t$, $t$Nie odrywaj dolnych pleców od podłogi.$t$),
  ($t$skip-a-szybki-bieg-z-wysokim-kolanem$t$, $t$Biegniesz w miejscu lub krótkim odcinkiem, unosząc kolana wysoko.$t$, $t$Stań prosto. Przebieraj nogami w miejscu, unosząc kolana do wysokości bioder, ręce pracują naprzemiennie z nogami. Lądujesz na przedniej części stopy.$t$, $t$Tułów prosto. Ręce pracują swobodnie. Lekkie, szybkie kroki.$t$, $t$Nie garb pleców.$t$),
  ($t$unoszenie-nogi-w-bok-lezac-na-boku$t$, $t$Leżysz na boku i unosisz górną nogę w bok.$t$, $t$Połóż się na boku, nogi proste i złączone. Unieś górną nogę w bok na około 45° i wolno opuść. Zrób serię i zmień stronę.$t$, $t$Biodra w jednej linii. Noga lekko do tyłu. Rób wolno.$t$, $t$Nie przewracaj się do tyłu.$t$),
  ($t$lopatkowe-podciagniecia-w-zwisie-scapular-pull-up$t$, $t$Wisisz na drążku z prostymi rękami i unosisz ciało, ściągając łopatki w dół.$t$, $t$Chwyć drążek i zwiśnij na prostych rękach. Nie uginając łokci, ściągnij łopatki w dół, tak by ciało lekko się uniosło. Wolno wróć.$t$, $t$Ręce proste. Barki daleko od uszu. Ruch mały i wolny.$t$, $t$Nie uginaj łokci.$t$),
  ($t$uginanie-nog-na-podlodze-glute-ham-raise$t$, $t$Klęczysz z unieruchomionymi stopami i wolno opuszczasz tułów do przodu, a potem się podciągasz.$t$, $t$Uklęknij, stopy unieruchom pod ławką lub sprzętem. Napnij pośladki i wolno opuszczaj tułów ku podłodze. Pomóż sobie rękami i wróć do pionu.$t$, $t$Tułów i uda w jednej linii. Opuszczaj bardzo wolno. Pomagaj sobie rękami.$t$, $t$Nie zginaj się w biodrach.$t$),
  ($t$brzuszki$t$, $t$Leżysz na plecach i unosisz łopatki nad podłogę, napinając brzuch.$t$, $t$Połóż się na plecach, kolana zgięte, ręce przy głowie. Unieś łopatki nad podłogę, napinając brzuch. Wolno wróć.$t$, $t$Szyja luźna. Ruch z brzucha. Oddychaj równo.$t$, $t$Nie ciągnij głowy rękami.$t$),
  ($t$wyciskanie-nad-glowe-z-guma-oporowa$t$, $t$Stoisz na gumie i wypychasz ręce nad głowę.$t$, $t$Stań na środku gumy, końce chwyć na wysokości barków. Wypchnij ręce nad głowę do wyprostu i wolno opuść.$t$, $t$Brzuch napięty. Nie wyginaj pleców. Guma stabilnie pod stopami.$t$, $t$Nie odchylaj się do tyłu.$t$),
  ($t$dzien-dobry-z-guma-oporowa-good-morning$t$, $t$Stoisz na gumie z jej końcami na karku i pochylasz tułów, odsuwając biodra do tyłu.$t$, $t$Stań na gumie, końce przełóż przez kark. Odsuń biodra do tyłu i pochyl tułów z prostymi plecami. Wróć do stania, popychając biodra do przodu.$t$, $t$Plecy proste. Kolana lekko ugięte. Ruch z bioder.$t$, $t$Nie zaokrąglaj pleców.$t$),
  ($t$wyprost-biodra-z-guma-oporowa$t$, $t$Odsuwasz nogę w tył, rozciągając gumę.$t$, $t$Zaczep gumę nisko i załóż ją na kostkę. Trzymając się czegoś, odsuń wyprostowaną nogę do tyłu i wolno wróć.$t$, $t$Tułów prosto. Ruch z pośladka. Rób wolno.$t$, $t$Nie wyginaj dolnych pleców.$t$),
  ($t$zgiecie-biodra-z-guma-oporowa$t$, $t$Unosisz kolano do przodu, rozciągając gumę.$t$, $t$Zaczep gumę nisko za sobą i załóż ją na kostkę. Trzymając się czegoś, unieś kolano do przodu i wolno wróć.$t$, $t$Tułów prosto. Ruch wolny. Lekka guma.$t$, $t$Nie odchylaj się do tyłu.$t$),
  ($t$unoszenie-ramion-bokiem-z-guma-oporowa$t$, $t$Stoisz na gumie i unosisz ręce w bok do wysokości barków.$t$, $t$Stań na gumie, końce chwyć w dłonie. Unieś ręce bokiem do wysokości barków i wolno opuść.$t$, $t$Łokcie lekko zgięte. Barki nisko. Bez bujania.$t$, $t$Nie unoś rąk powyżej barków.$t$),
  ($t$rotacja-wewnetrzna-barku-z-guma-oporowa$t$, $t$Łokieć masz przy boku i obracasz przedramię do brzucha, rozciągając gumę.$t$, $t$Zaczep gumę z boku, łokieć zgięty do kąta prostego, przy ciele. Obróć przedramię do brzucha i wolno wróć.$t$, $t$Łokieć przy ciele. Ruch wolny. Lekka guma.$t$, $t$Nie odsuwaj łokcia od ciała.$t$),
  ($t$wspiecia-na-palce-z-guma-oporowa$t$, $t$Siedzisz z gumą na stopie i prostujesz stopę, unosząc piętę.$t$, $t$Usiądź z wyprostowaną nogą, gumę załóż na przód stopy i trzymaj końce w dłoniach. Wypchnij stopę do przodu i wolno wróć.$t$, $t$Ruch wolny i pełny. Kolano proste. Lekka guma.$t$, $t$Nie rób ruchu szybko.$t$),
  ($t$odwodzenie-nogi-w-tyl-na-czworakach$t$, $t$Na czworakach odsuwasz zgiętą nogę w tył i w górę.$t$, $t$Stań na czworakach, dłonie pod barkami. Unieś zgiętą nogę stopą ku sufitowi i wolno opuść. Zrób serię i zmień nogę.$t$, $t$Plecy proste. Biodra równo. Ruch z pośladka.$t$, $t$Nie wyginaj dolnych pleców.$t$),
  ($t$pompki-na-podwyzszeniu-waskim-chwytem$t$, $t$Robisz pompkę z dłońmi blisko siebie na podwyższeniu.$t$, $t$Oprzyj dłonie o ławkę blisko siebie, pod klatką. Ciało w jednej linii. Zegnij łokcie, trzymając je przy ciele, i wypchnij się w górę.$t$, $t$Brzuch napięty. Łokcie przy ciele. Ciało w linii.$t$, $t$Nie opuszczaj bioder.$t$),
  ($t$pompki-na-podwyzszeniu-szerokim-chwytem$t$, $t$Robisz pompkę z dłońmi szeroko na podwyższeniu.$t$, $t$Oprzyj dłonie o ławkę szerzej niż barki. Ciało w jednej linii. Zegnij łokcie i zbliż klatkę do ławki, potem wypchnij się w górę.$t$, $t$Brzuch napięty. Nie rozstawiaj rąk za szeroko. Ciało w linii.$t$, $t$Nie opuszczaj bioder.$t$),
  ($t$odwrotne-rozpietki-z-guma-oporowa$t$, $t$Rozciągasz gumę przed sobą, odwodząc ręce w tył.$t$, $t$Stań, gumę trzymaj oburącz przed sobą. Rozciągnij ją, rozkładając ręce na boki i ściągając łopatki. Wolno wróć.$t$, $t$Ręce lekko zgięte. Łopatki do siebie. Barki nisko.$t$, $t$Nie unoś barków.$t$),
  ($t$dipy-na-poreczach-akcent-triceps$t$, $t$Opierasz się na poręczach i uginasz łokcie, opuszczając ciało, tułów prosto.$t$, $t$Wejdź na poręcze na prostych rękach, tułów prosto. Zegnij łokcie, trzymając je przy ciele, i opuść ciało. Wypchnij się w górę.$t$, $t$Tułów prosto. Łokcie przy ciele. Schodź tylko tak nisko, jak komfortowo.$t$, $t$Nie unoś barków do uszu.$t$),
  ($t$pompki-z-biodrami-w-gorze-pike$t$, $t$Stoisz w pozycji odwróconej litery V i uginasz ręce, opuszczając głowę ku podłodze.$t$, $t$Oprzyj dłonie i stopy na podłodze, biodra wysoko, ciało tworzy odwróconą literę V. Zegnij łokcie, opuszczając głowę ku podłodze, i wypchnij się.$t$, $t$Biodra wysoko. Głowa między rękami. Ruch wolny.$t$, $t$Nie opuszczaj bioder.$t$),
  ($t$uginanie-ramion-z-guma-oporowa$t$, $t$Stoisz na gumie i uginasz ramiona.$t$, $t$Stań na środku gumy, końce chwyć w dłonie. Zegnij łokcie i unieś dłonie do barków. Wolno opuść.$t$, $t$Łokcie przy bokach. Plecy proste. Opuszczaj wolno.$t$, $t$Nie bujaj tułowiem.$t$),
  ($t$pallof-press-z-guma-oporowa$t$, $t$Stoisz bokiem do gumy i wypychasz ręce przed siebie, nie dając się skręcić.$t$, $t$Zaczep gumę na wysokości klatki, stań bokiem. Trzymaj ją przy klatce, wypchnij ręce przed siebie i przytrzymaj. Wróć do klatki.$t$, $t$Biodra i barki prosto przed siebie. Brzuch napięty. Oddychaj.$t$, $t$Nie pozwól, by guma skręcała tułów.$t$),
  ($t$sciaganie-gumy-oporowej-z-gory$t$, $t$Ściągasz gumę zaczepioną wysoko w dół do klatki.$t$, $t$Zaczep gumę wysoko, stań lub uklęknij przodem. Chwyć końce i ściągnij je w dół do klatki, łokcie w dół. Wolno wróć.$t$, $t$Klatka lekko do przodu. Łokcie w dół. Ciągnij plecami.$t$, $t$Nie odchylaj się do tyłu.$t$),
  ($t$wyciskanie-gumy-oporowej-przed-siebie$t$, $t$Wypychasz gumę przed siebie, jakbyś robił wyciskanie.$t$, $t$Przełóż gumę za plecami i chwyć końce przy klatce. Wypchnij ręce przed siebie do wyprostu i wolno wróć.$t$, $t$Plecy proste. Barki nisko. Guma napięta.$t$, $t$Nie unoś barków.$t$),
  ($t$pompki-lopatkowe$t$, $t$W pozycji do pompki ściągasz i rozsuwasz łopatki bez uginania łokci.$t$, $t$Przyjmij pozycję do pompki na prostych rękach. Nie uginając łokci, opuść klatkę o kilka centymetrów, ściągając łopatki, a potem je rozsuń.$t$, $t$Ręce proste. Ruch mały. Brzuch napięty.$t$, $t$Nie uginaj łokci.$t$),
  ($t$unoszenie-palcow-stop-tibialis-raise$t$, $t$Stoisz piętami przy ścianie i unosisz palce stóp do góry.$t$, $t$Stań plecami do ściany, pięty kilka centymetrów od niej. Unieś palce stóp jak najwyżej i wolno opuść.$t$, $t$Ruch wolny. Pięty na podłodze. Tułów oparty o ścianę.$t$, $t$Nie odrywaj pięt.$t$),
  ($t$face-pull-z-guma-oporowa$t$, $t$Przyciągasz gumę do twarzy, rozchylając ręce na boki.$t$, $t$Zaczep gumę na wysokości twarzy. Chwyć końce i przyciągnij je do twarzy, łokcie szeroko i wysoko. Wolno wróć.$t$, $t$Łokcie wysoko. Łopatki do siebie. Lekka guma.$t$, $t$Nie odchylaj się do tyłu.$t$),
  ($t$unoszenie-y-z-guma-oporowa$t$, $t$Rozciągasz gumę, unosząc ręce w górę i na boki, jak litera Y.$t$, $t$Stań na gumie lub zaczep ją nisko. Chwyć końce i unieś ręce po skosie w górę, tworząc literę Y. Wolno opuść.$t$, $t$Barki nisko. Ręce lekko zgięte. Rób wolno.$t$, $t$Nie unoś barków do uszu.$t$),
  ($t$przysiad-z-guma-oporowa$t$, $t$Stoisz na gumie i robisz przysiad.$t$, $t$Stań na środku gumy, końce trzymaj przy barkach. Zegnij kolana i biodra i zejdź w dół, plecy proste. Wypchnij się piętami do stania.$t$, $t$Plecy proste. Kolana w linii stóp. Pięty na podłodze.$t$, $t$Nie pozwalaj kolanom uciekać do środka.$t$),
